/* v44 — Assetهای تصویری اختصاصی کاربر (پرتره/اسپرایت/مدارک) — تولید خودکار */
const ASSETS44 = {"portrait": {"arash": "data:image/png;base64,", "arshan": "data:image/png;base64,", "maryam": "data:image/png;base64,", "sara": "data:image/png;base64,", "m1": "data:image/png;base64,", "m2": "data:image/png;base64,", "m3": "data:image/png;base64,", "m4": "data:image/png;base64,"}, "walk": {"arash": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "arshan": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "maryam": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "sara": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, "merchantWalk": {"1": [], "2": [], "3": [], "4": []}, "merchantCard": {"1": "data:image/png;base64,", "2": "data:image/png;base64,", "3": "data:image/png;base64,", "4": "data:image/png;base64,"}, "docs": {"docZ": "data:image/png;base64,", "docFile": "data:image/png;base64,"}};
try {
  /* تبدیل data-URI به Image برای استفاده در Canvas */
  ASSETS44.portrait = Object.fromEntries(Object.entries(ASSETS44.portrait).map(([k, u]) => {
    const im = new Image(); im.src = u; return [k, im];
  }));
  ASSETS44.merchantCard = Object.fromEntries(Object.entries(ASSETS44.merchantCard).map(([k, u]) => {
    const im = new Image(); im.src = u; return [k, im];
  }));
  ASSETS44.docs = Object.fromEntries(Object.entries(ASSETS44.docs).map(([k, u]) => {
    const im = new Image(); im.src = u; return [k, im];
  }));
  ASSETS44.walk = Object.fromEntries(Object.entries(ASSETS44.walk).map(([k, arr]) => [k, arr.map(u => { const im = new Image(); im.src = u; return im; })]));
  ASSETS44.merchantWalk = Object.fromEntries(Object.entries(ASSETS44.merchantWalk).map(([k, arr]) => [k, arr.map(u => { const im = new Image(); im.src = u; return im; })]));
} catch (e) { console.warn('[v44] assets init failed', e); }
